package foodchain

import "strings"

// Each verse is built from an animal, an optional comment line,
// and the cumulative chain of what each animal was swallowed to catch.
var animals = []string{
	"fly",
	"spider",
	"bird",
	"cat",
	"dog",
	"goat",
	"cow",
	"horse",
}

var comments = []string{
	"",
	"It wriggled and jiggled and tickled inside her.",
	"How absurd to swallow a bird!",
	"Imagine that, to swallow a cat!",
	"What a hog, to swallow a dog!",
	"Just opened her throat and swallowed a goat!",
	"I don't know how she swallowed a cow!",
	"She's dead, of course!",
}

const dieLine = "I don't know why she swallowed the fly. Perhaps she'll die."

// Verse returns the v-th verse of the song (1-based).
func Verse(v int) string {
	var b strings.Builder
	b.WriteString("I know an old lady who swallowed a " + animals[v-1] + ".\n")
	if c := comments[v-1]; c != "" {
		b.WriteString(c + "\n")
	}
	// Cumulative chain: each animal was swallowed to catch the previous one.
	for i := v - 1; i >= 1; i-- {
		b.WriteString("She swallowed the " + animals[i] + " to catch the " + caught(i) + ".\n")
	}
	if v < len(animals) {
		b.WriteString(dieLine)
	}
	return b.String()
}

// caught returns the animal that animals[i] was swallowed to catch,
// including the special phrasing used for the spider.
func caught(i int) string {
	if i == 1 {
		return "spider that wriggled and jiggled and tickled inside her"
	}
	return animals[i-1]
}

// Verses returns the verses from start to end, separated by a blank line.
func Verses(start, end int) string {
	verses := make([]string, 0, end-start+1)
	for v := start; v <= end; v++ {
		verses = append(verses, Verse(v))
	}
	return strings.Join(verses, "\n\n")
}

// Song returns the entire song.
func Song() string {
	return Verses(1, len(animals))
}

